#include "include/asian.hpp"
#include <iostream>
#include <iomanip>
#include <chrono>

int main() {
    // Test parameters
    double S0 = 100.0;
    double K = 100.0;
    double r = 0.05;
    double q = 0.02;
    double sigma = 0.2;
    double T = 1.0;
    int n = 12;
    std::uint64_t seed = 42;

    std::cout << std::fixed << std::setprecision(6);

    // Test with 1 million paths to check performance
    std::int64_t paths = 1000000;

    auto start = std::chrono::high_resolution_clock::now();
    mc::McResult result = mc::arithmetic_asian_call(S0, K, r, q, sigma, T, n, paths, seed, true);
    auto end = std::chrono::high_resolution_clock::now();

    auto duration = std::chrono::duration_cast<std::chrono::milliseconds>(end - start);

    std::cout << "Performance Test Results:" << std::endl;
    std::cout << "Paths: " << paths << std::endl;
    std::cout << "Time taken: " << duration.count() << " ms" << std::endl;
    std::cout << "Price: " << result.price << std::endl;
    std::cout << "Standard Error: " << result.std_error << std::endl;

    // Check if it's under a second for 1 million paths
    if (duration.count() < 1000) {
        std::cout << "✓ Performance requirement met: < 1 second for 1M paths" << std::endl;
    } else {
        std::cout << "✗ Performance requirement not met: > 1 second for 1M paths" << std::endl;
    }

    return 0;
}

