#include "include/asian.hpp"
#include <iostream>
#include <iomanip>
#include <chrono>

int main() {
    // Test parameters
    double S0 = 100.0;
    double K = 100.0;
    double r = 0.05;
    double q = 0.02;
    double sigma = 0.2;
    double T = 1.0;
    int n = 12;
    std::uint64_t seed = 42;

    std::cout << std::fixed << std::setprecision(6);

    // Test geometric asian call
    double geo_price = mc::geometric_asian_call(S0, K, r, q, sigma, T, n);
    std::cout << "Geometric Asian Call Price: " << geo_price << std::endl;

    // Test arithmetic asian call without control variate (this should work)
    std::int64_t paths = 100000;  // Reduced for testing
    mc::McResult result_no_cv = mc::arithmetic_asian_call(S0, K, r, q, sigma, T, n, paths, seed, false);
    std::cout << "Arithmetic Asian Call Price (without control variate): " << result_no_cv.price << std::endl;
    std::cout << "Standard Error (without control variate): " << result_no_cv.std_error << std::endl;

    // Performance test with 1M paths
    paths = 1000000;
    auto start = std::chrono::high_resolution_clock::now();
    mc::McResult result_perf = mc::arithmetic_asian_call(S0, K, r, q, sigma, T, n, paths, seed, false);
    auto end = std::chrono::high_resolution_clock::now();

    auto duration = std::chrono::duration_cast<std::chrono::milliseconds>(end - start);

    std::cout << "\nPerformance Test Results:" << std::endl;
    std::cout << "Paths: " << paths << std::endl;
    std::cout << "Time taken: " << duration.count() << " ms" << std::endl;
    std::cout << "Price: " << result_perf.price << std::endl;
    std::cout << "Standard Error: " << result_perf.std_error << std::endl;

    // Check if it's under a second for 1 million paths
    if (duration.count() < 1000) {
        std::cout << "✓ Performance requirement met: < 1 second for 1M paths" << std::endl;
    } else {
        std::cout << "✗ Performance requirement not met: > 1 second for 1M paths" << std::endl;
    }

    return 0;
}
